<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Plus, RotateCcw, Save, Trash2, UserRound, X } from 'lucide-vue-next'
import SectionPanel from '../components/SectionPanel.vue'
import StatusBadge from '../components/StatusBadge.vue'
import WorkspaceStickyStack from '../components/WorkspaceStickyStack.vue'
import { ownersApi, type FiscalPeriodRecord, type OwnerRecord, type OwnerTransactionRecord } from '../api/owners'
import { accountingApi, type FinancialAccountRecord } from '../api/accounting'
import { formatMoney, formatMoneyInput, parseMoneyInput } from '../utils/currency'
import { formatDateTime } from '../utils/date'
import JalaliDatePicker from '../components/JalaliDatePicker.vue'
import { confirmAction, normalizeError } from '../ui/feedback'
import SelectField from '../components/SelectField.vue'

const props = defineProps<{ currencyUnit: 'Rial' | 'Toman' }>()
const emit = defineEmits<{ notify: [string] }>()
type Tab = 'Overview' | 'Owners' | 'Transactions' | 'Capital & Drawings' | 'Loans / Current Accounts' | 'Profit Allocation'
const tabs: Tab[] = ['Overview', 'Owners', 'Transactions', 'Capital & Drawings', 'Loans / Current Accounts', 'Profit Allocation']
const tab = ref<Tab>('Overview'); const owners = ref<OwnerRecord[]>([]); const transactions = ref<OwnerTransactionRecord[]>([]); const periods = ref<FiscalPeriodRecord[]>([]); const accounts = ref<FinancialAccountRecord[]>([])
const selectedOwner = ref<string>(''); const selectedPeriod = ref<string>(''); const error = ref(''); const editing = ref(false); const saving = ref(false)
const ownerForm = ref({ name: '', phone: '', email: '', notes: '', ownershipBps: 0, profitSharingBps: 0 })
const shareForm = ref({ ownershipBps: 0, profitSharingBps: 0 })
const txForm = ref({ type: 'capital_contribution', amountText: '', financialAccountId: '', categoryAccountId: 'ACC-EXP-OTHER', description: '', occurredAt: null as string|null, notes: '' })
const periodForm = ref({ name: '', startDate: null as string|null, endDate: null as string|null, notes: '' })
const currentOwner = computed(() => owners.value.find(x => x.id === selectedOwner.value) ?? null)
const selectedPeriodRow = computed(() => periods.value.find(x => x.id === selectedPeriod.value) ?? null)
const filteredTransactions = computed(() => transactions.value.filter(x => !selectedOwner.value || x.ownerId === selectedOwner.value))
const ownerName = (id:string) => owners.value.find(x => x.id === id)?.name ?? id
const money = (v:number) => formatMoney(v, props.currencyUnit)
async function load() { try { [owners.value, periods.value, accounts.value] = await Promise.all([ownersApi.list(false), ownersApi.periods(), accountingApi.financialAccounts()]); if (!selectedOwner.value) selectedOwner.value = owners.value[0]?.id ?? ''; if (!selectedPeriod.value) selectedPeriod.value = periods.value[0]?.id ?? ''; syncShares(); await loadTransactions() } catch (e) { error.value = String(e) } }
function syncShares(){if(currentOwner.value)shareForm.value={ownershipBps:currentOwner.value.ownershipBps,profitSharingBps:currentOwner.value.profitSharingBps}}
async function loadTransactions() { try { transactions.value = await ownersApi.transactions(selectedOwner.value) } catch (e) { error.value = String(e) } }
function startOwner() { ownerForm.value = { name:'', phone:'', email:'', notes:'', ownershipBps:0, profitSharingBps:0 }; editing.value = true; tab.value = 'Owners' }
async function saveOwner() { saving.value=true;try { const v=await ownersApi.create(ownerForm.value); owners.value=[v,...owners.value];selectedOwner.value=v.id;editing.value=false;emit('notify','Owner saved.')}catch(e){error.value=String(e)}finally{saving.value=false} }
async function saveShares(){if(!currentOwner.value)return;try{const v=await ownersApi.updateShares(currentOwner.value.id,shareForm.value);owners.value=owners.value.map(x=>x.id===v.id?v:x);emit('notify','Owner shares updated.')}catch(e){error.value=String(e)}}
async function setActive(){if(!currentOwner.value)return;try{if(currentOwner.value.active)await ownersApi.archive(currentOwner.value.id);else await ownersApi.reactivate(currentOwner.value.id);await load()}catch(e){error.value=String(e)}}
async function deleteOwner(){if(!currentOwner.value||!(await confirmAction({title:'Delete owner',message:'Delete this owner permanently when safe?',confirmLabel:'Delete owner',danger:true})))return;try{await ownersApi.delete(currentOwner.value.id);owners.value=owners.value.filter(x=>x.id!==currentOwner.value!.id);selectedOwner.value=owners.value[0]?.id??'';emit('notify','Owner deleted.')}catch(e){error.value=normalizeError(e).message}}
async function postTransaction() { if (!selectedOwner.value) return; const amount=parseMoneyInput(txForm.value.amountText,props.currencyUnit); if (amount===null||amount<=0){error.value='Enter a valid positive amount.';return} try { await ownersApi.createTransaction({...txForm.value,ownerId:selectedOwner.value,amountRial:amount}); await load(); emit('notify','Owner transaction posted.')} catch(e){error.value=String(e)} }
async function createPeriod() { try { const v=await ownersApi.createPeriod(periodForm.value);periods.value=[v,...periods.value];selectedPeriod.value=v.id;emit('notify','Fiscal period created.')}catch(e){error.value=String(e)} }
async function previewPeriod() { if(!selectedPeriod.value)return;try{const v=await ownersApi.previewPeriod(selectedPeriod.value);periods.value=periods.value.map(x=>x.id===v.id?v:x)}catch(e){error.value=String(e)} }
async function closePeriod() { if(!selectedPeriod.value||!(await confirmAction({title:'Close fiscal period',message:'Close this fiscal period permanently?',confirmLabel:'Close period',danger:true})))return;try{const v=await ownersApi.closePeriod(selectedPeriod.value);periods.value=periods.value.map(x=>x.id===v.id?v:x);emit('notify','Fiscal period closed.')}catch(e){error.value=normalizeError(e).message} }
onMounted(load)
</script>
<template>
  <div>
    <WorkspaceStickyStack><header><div><p>Finance / ownership</p><h1>Owners & fiscal periods</h1><p>Keep capital, current accounts, and period allocations authoritative in the ledger.</p></div><button class="btn btn-ghost" type="button" @click="startOwner"><Plus :size="16"/> New owner</button></header><nav aria-label="Owner workspace"><button class="btn btn-sm" v-for="item in tabs" :key="item" type="button" :class="tab === item ? 'btn-primary' : 'btn-ghost'" @click="tab=item">{{ item }}</button></nav></WorkspaceStickyStack>
    <div v-if="error" role="alert">{{ error }} <button class="btn btn-ghost" @click="error=''" aria-label="Dismiss"><X :size="14"/></button></div>
    <section v-if="tab==='Overview'"><SectionPanel title="Ownership overview" subtitle="Balances are derived from posted journal lines."><div><button v-for="o in owners" :key="o.id" :class="{ 'bg-base-300': selectedOwner === o.id }" @click="selectedOwner=o.id;tab='Owners'"><UserRound :size="18"/><strong>{{o.name}}</strong><span>{{o.profitSharingBps/100}}% profit share</span><b>{{money(o.currentBalanceRial)}}</b></button></div></SectionPanel><SectionPanel title="Fiscal periods" subtitle="P&L is calculated only from journal lines."><div><button v-for="p in periods" :key="p.id" :class="{ 'bg-base-300': selectedPeriod === p.id }" @click="selectedPeriod=p.id;tab='Profit Allocation'"><span><strong>{{p.name}}</strong><small>{{formatDateTime(p.startDate)}} – {{formatDateTime(p.endDate)}}</small></span><StatusBadge :label="p.status" :tone="p.status==='Closed'?'slate':'amber'"/><b>{{money(p.profitLossRial)}}</b></button><p v-if="!periods.length">No fiscal periods yet.</p></div></SectionPanel></section>
    <section v-else-if="tab==='Owners'"><SectionPanel title="Owner register" subtitle="Ownership and profit-sharing are independent fixed-scale percentages."><div><table class="table table-zebra w-full"><thead><tr><th>Owner</th><th>Ownership</th><th>Profit share</th><th>Current balance</th></tr></thead><tbody><tr v-for="o in owners" :key="o.id" :class="{'bg-base-300':selectedOwner===o.id}" @click="selectedOwner=o.id;syncShares()"><td><span>{{o.name}}</span><span>{{o.active?'Active':'Archived'}}</span></td><td>{{o.ownershipBps/100}}%</td><td>{{o.profitSharingBps/100}}%</td><td>{{money(o.currentBalanceRial)}}</td></tr></tbody></table></div></SectionPanel><SectionPanel v-if="editing" title="New owner" subtitle="Percentages are stored as basis points, never floats."><form @submit.prevent="saveOwner"><label class="form-control gap-1"><span>Name</span><input class="input input-bordered w-full min-w-0" v-model="ownerForm.name" required /></label><div><label class="form-control gap-1"><span>Ownership % (bps)</span><input class="input input-bordered w-full min-w-0" v-model.number="ownerForm.ownershipBps" type="number" min="0" max="10000" required /></label><label class="form-control gap-1"><span>Profit share % (bps)</span><input class="input input-bordered w-full min-w-0" v-model.number="ownerForm.profitSharingBps" type="number" min="0" max="10000" required /></label></div><label class="form-control gap-1"><span>Phone</span><input class="input input-bordered w-full min-w-0" v-model="ownerForm.phone" /></label><label class="form-control gap-1"><span>Email</span><input class="input input-bordered w-full min-w-0" v-model="ownerForm.email" type="email" /></label><label class="form-control gap-1"><span>Notes</span><textarea class="textarea textarea-bordered w-full min-w-0" v-model="ownerForm.notes" rows="3"/></label><div><button class="btn btn-ghost" type="button" @click="editing=false">Cancel</button><button class="btn btn-ghost" :disabled="saving"><Save :size="15"/> Save</button></div></form></SectionPanel><SectionPanel v-else-if="currentOwner" title="Owner inspector" subtitle="Posted history is immutable; corrections are reversals."><div><div><UserRound :size="19"/></div><div><h3>{{currentOwner.name}}</h3><p>{{currentOwner.ownershipBps/100}}% ownership · {{currentOwner.profitSharingBps/100}}% profit share</p></div></div><form @submit.prevent="saveShares"><div><label class="form-control gap-1"><span>Ownership bps</span><input class="input input-bordered w-full min-w-0" v-model.number="shareForm.ownershipBps" type="number" min="0" max="10000"/></label><label class="form-control gap-1"><span>Profit share bps</span><input class="input input-bordered w-full min-w-0" v-model.number="shareForm.profitSharingBps" type="number" min="0" max="10000"/></label></div><button class="btn btn-ghost"><Save :size="15"/> Save future shares</button></form><dl><div><dt>Capital</dt><dd>{{money(currentOwner.capitalContributedRial)}}</dd></div><div><dt>Drawings</dt><dd>{{money(currentOwner.drawingsRial)}}</dd></div><div><dt>Current / payable</dt><dd>{{money(currentOwner.currentBalanceRial)}}</dd></div><div><dt>Loans payable</dt><dd>{{money(currentOwner.loanPayableRial)}}</dd></div><div><dt>Loans receivable</dt><dd>{{money(currentOwner.loanReceivableRial)}}</dd></div><div><dt>Allocated P/L</dt><dd>{{money(currentOwner.allocatedProfitLossRial)}}</dd></div></dl><div><button class="btn btn-ghost" @click="tab='Transactions';loadTransactions">View transactions</button><button class="btn btn-ghost" @click="setActive"><RotateCcw :size="15"/> {{currentOwner.active?'Archive':'Reactivate'}}</button><button class="btn btn-ghost" @click="deleteOwner"><Trash2 :size="15"/> Delete</button></div></SectionPanel></section>
    <section v-else-if="tab==='Transactions'||tab==='Capital & Drawings'||tab==='Loans / Current Accounts'"><SectionPanel title="Post owner transaction" subtitle="Every action becomes one balanced integer-Rial journal entry."><form @submit.prevent="postTransaction"><SelectField v-model="selectedOwner" label="Owner" :options="owners.map((owner) => ({ label: owner.name, value: owner.id }))" /><SelectField v-model="txForm.type" label="Type" :options="[{ label: 'Capital contribution', value: 'capital_contribution' }, { label: 'Drawing (not an expense)', value: 'drawing' }, { label: 'Business expense paid personally', value: 'owner_paid_expense' }, { label: 'Owner reimbursement', value: 'owner_reimbursement' }, { label: 'Owner → business loan', value: 'loan_to_business' }, { label: 'Business → owner loan', value: 'loan_from_business' }, { label: 'Repay owner loan', value: 'loan_repayment_to_owner' }, { label: 'Receive owner loan repayment', value: 'loan_repayment_from_owner' }]" /><label class="form-control gap-1"><span>Amount ({{currencyUnit}})</span><input class="input input-bordered w-full min-w-0" v-model="txForm.amountText" inputmode="decimal" required @blur="txForm.amountText=formatMoneyInput(parseMoneyInput(txForm.amountText,currencyUnit)||0,currencyUnit)" /></label><SelectField v-if="txForm.type!=='owner_paid_expense'" v-model="txForm.financialAccountId" label="Cash / bank account" :options="[{ label: 'Select account', value: '' }, ...accounts.map((account) => ({ label: account.name, value: account.id }))]" /><label class="form-control gap-1" v-else><span>Expense category account</span><input class="input input-bordered w-full min-w-0" v-model="txForm.categoryAccountId" required /></label><label class="form-control gap-1"><span>Description</span><input class="input input-bordered w-full min-w-0" v-model="txForm.description" /></label><button class="btn btn-ghost">Post transaction</button></form></SectionPanel><SectionPanel title="Owner transaction history" subtitle="Derived balances remain stable after reversals."><div><table class="table table-zebra w-full"><thead><tr><th>Number</th><th>Owner</th><th>Type</th><th>Amount</th><th>Date</th><th></th></tr></thead><tbody><tr v-for="x in filteredTransactions" :key="x.id"><td>{{x.transactionNumber}}</td><td>{{ownerName(x.ownerId)}}</td><td>{{x.type}}</td><td>{{money(x.amountRial)}}</td><td>{{formatDateTime(x.occurredAt)}}</td><td><button class="btn btn-ghost" v-if="x.status==='Posted'" @click="ownersApi.reverseTransaction(x.id).then(load)">Reverse</button></td></tr></tbody></table></div></SectionPanel></section>
    <section v-else-if="tab==='Profit Allocation'">
      <SectionPanel title="Fiscal periods" subtitle="Close once; the profit-sharing snapshot is preserved forever.">
        <div><button v-for="p in periods" :key="p.id" :class="{ 'bg-base-300': selectedPeriod === p.id }" @click="selectedPeriod=p.id"><span><strong>{{p.name}}</strong><small>{{formatDateTime(p.startDate)}} – {{formatDateTime(p.endDate)}}</small></span><StatusBadge :label="p.status" :tone="p.status==='Closed'?'slate':'amber'"/><b>{{money(p.profitLossRial)}}</b></button></div>
        <form @submit.prevent="createPeriod"><h3>New period</h3><label class="form-control gap-1"><span>Name</span><input class="input input-bordered w-full min-w-0" v-model="periodForm.name" required placeholder="1405"/></label><div><label class="form-control gap-1"><span>Start date</span><JalaliDatePicker v-model="periodForm.startDate" /></label><label class="form-control gap-1"><span>End date</span><JalaliDatePicker v-model="periodForm.endDate" /></label></div><button class="btn btn-ghost">Create period</button></form>
      </SectionPanel>
      <SectionPanel v-if="selectedPeriodRow" title="Closing preview" subtitle="Revenue − COGS − expenses, from journal lines only."><dl><div><dt>Revenue</dt><dd>{{money(selectedPeriodRow.revenueRial)}}</dd></div><div><dt>COGS</dt><dd>{{money(selectedPeriodRow.cogsRial)}}</dd></div><div><dt>Expenses</dt><dd>{{money(selectedPeriodRow.expensesRial)}}</dd></div><div><dt>Profit / loss</dt><dd>{{money(selectedPeriodRow.profitLossRial)}}</dd></div></dl><div><button class="btn btn-ghost" @click="previewPeriod">Refresh preview</button><button class="btn btn-ghost" v-if="selectedPeriodRow.status==='Open'" @click="closePeriod">Close period</button></div><h3>Owner allocation</h3><div v-for="a in (selectedPeriodRow.previewAllocations?.length?selectedPeriodRow.previewAllocations:selectedPeriodRow.allocations)" :key="a.ownerId"><span>{{ownerName(a.ownerId)}} · {{a.profitSharingBps/100}}%</span><b>{{money(a.amountRial)}}</b></div></SectionPanel>
    </section>
  </div>
</template>
